ALTER TABLE public.rental_expenses ADD COLUMN installments integer NOT NULL DEFAULT 1 CHECK(installments BETWEEN 1 AND 24);
CREATE UNIQUE INDEX credit_once_per_expense_charge ON public.credit_allocations(expense_id,charge_id);
CREATE OR REPLACE FUNCTION public.apply_rent_credits(_tenancy uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.rental_expenses; c record; a numeric; cap numeric; BEGIN IF auth.uid() IS NOT NULL AND NOT public.contract_owner(_tenancy) THEN RAISE EXCEPTION 'Sin permiso'; END IF; PERFORM 1 FROM public.tenancies WHERE id=_tenancy FOR UPDATE; FOR e IN SELECT * FROM public.rental_expenses WHERE tenancy_id=_tenancy AND unapplied_credit>0 ORDER BY created_at FOR UPDATE LOOP cap:=ceil(e.amount/e.installments*100)/100; FOR c IN SELECT r.*,r.amount-r.credit_applied-coalesce((SELECT sum(p.amount) FROM public.payments p WHERE p.charge_id=r.id AND p.confirmation_status='confirmed'),0) AS remaining FROM public.rent_charges r WHERE r.tenancy_id=_tenancy AND NOT EXISTS(SELECT 1 FROM public.credit_allocations ca WHERE ca.charge_id=r.id AND ca.expense_id=e.id) ORDER BY due_on FOR UPDATE LOOP a:=least(e.unapplied_credit,greatest(c.remaining,0),cap); IF a>0 THEN UPDATE public.rent_charges SET credit_applied=credit_applied+a WHERE id=c.id; INSERT INTO public.credit_allocations(expense_id,charge_id,amount) VALUES(e.id,c.id,a); e.unapplied_credit:=e.unapplied_credit-a; END IF; EXIT WHEN e.unapplied_credit<=0; END LOOP; UPDATE public.rental_expenses SET unapplied_credit=e.unapplied_credit WHERE id=e.id; END LOOP; END; $$;
CREATE FUNCTION public.credit_new_charge() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.apply_rent_credits(NEW.tenancy_id); RETURN NEW; END; $$;
CREATE TRIGGER credit_new_charge AFTER INSERT ON public.rent_charges FOR EACH ROW EXECUTE FUNCTION public.credit_new_charge();
CREATE OR REPLACE FUNCTION public.resolve_repair(_issue uuid,_cost numeric,_months integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.issues; BEGIN SELECT * INTO i FROM public.issues WHERE id=_issue FOR UPDATE; IF NOT FOUND OR i.landlord_id<>auth.uid() THEN RAISE EXCEPTION 'Sin permiso'; END IF; IF i.status='resolved' THEN RETURN; END IF; IF _cost<0 OR (_months IS NOT NULL AND _months NOT BETWEEN 1 AND 120) THEN RAISE EXCEPTION 'Costo o periodicidad inválidos'; END IF; IF i.tenancy_id IS NOT NULL AND _cost>0 THEN INSERT INTO public.rental_expenses(tenancy_id,property_id,category,amount,payer,reimbursement,issue_id,note,installments) VALUES(i.tenancy_id,i.property_id,'repair',_cost,CASE WHEN i.payer='landlord' THEN 'landlord' ELSE 'tenant' END,CASE WHEN i.payer='tenant_credit' THEN 'rent_credit' ELSE 'none' END,i.id,i.title,CASE WHEN i.reimbursement_mode='installments' THEN coalesce(i.reimbursement_months,1) ELSE 1 END) ON CONFLICT(issue_id) DO NOTHING; END IF; INSERT INTO public.maintenance_records(landlord_id,property_id,title,category,repaired_on,next_due_on,cost) VALUES(i.landlord_id,i.property_id,i.title,'maintenance',CURRENT_DATE,CASE WHEN _months IS NOT NULL THEN (CURRENT_DATE+make_interval(months=>_months))::date ELSE NULL END,_cost); UPDATE public.issues SET status='resolved',actual_cost=_cost WHERE id=i.id; END; $$;
CREATE FUNCTION public.protect_issue_parties() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.landlord_id<>OLD.landlord_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.property_id<>OLD.property_id OR NEW.tenancy_id IS DISTINCT FROM OLD.tenancy_id THEN RAISE EXCEPTION 'No puedes cambiar las partes de una reparación'; END IF; IF NEW.status NOT IN ('open','reviewing','approved','in_progress','resolved','closed') THEN RAISE EXCEPTION 'Estado inválido'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_issue_parties BEFORE UPDATE ON public.issues FOR EACH ROW EXECUTE FUNCTION public.protect_issue_parties();
CREATE POLICY "Manual payments connected property" ON public.payments AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK((property_id IS NULL AND tenant_id IS NULL) OR EXISTS(SELECT 1 FROM public.properties p WHERE p.id=payments.property_id AND p.landlord_id=auth.uid() AND (payments.tenant_id IS NULL OR EXISTS(SELECT 1 FROM public.tenancies t WHERE t.property_id=p.id AND t.tenant_id=payments.tenant_id AND t.landlord_id=auth.uid()))));
CREATE FUNCTION public.validate_issue_media() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE path text; videos int:=0; BEGIN IF cardinality(NEW.media_paths)>5 THEN RAISE EXCEPTION 'Máximo 5 fotos'; END IF; FOREACH path IN ARRAY NEW.media_paths LOOP IF split_part(path,'/',1)<>NEW.tenancy_id::text OR split_part(path,'/',2)<>NEW.tenant_id::text OR path !~ '\.(jpg|jpeg|png|webp|mp4|webm)$' THEN RAISE EXCEPTION 'Archivo inválido'; END IF; IF path ~ '\.(mp4|webm)$' THEN videos:=videos+1; END IF; END LOOP; IF videos>0 AND cardinality(NEW.media_paths)<>1 THEN RAISE EXCEPTION 'Un video o hasta cinco fotos'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_issue_media BEFORE INSERT OR UPDATE OF media_paths ON public.issues FOR EACH ROW EXECUTE FUNCTION public.validate_issue_media();
ALTER TABLE public.notifications ADD COLUMN event_key text UNIQUE;
CREATE FUNCTION public.refresh_rental_reminders() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tenancies; c record; today date:=(now() AT TIME ZONE 'America/Mexico_City')::date; BEGIN FOR t IN SELECT * FROM public.tenancies WHERE status IN ('active','expiring') LOOP PERFORM public.generate_rent_charges(t.id); END LOOP; FOR c IN SELECT r.*,t.tenant_id,t.landlord_id,t.end_date,t.grace_days,p.name FROM public.rent_charges r JOIN public.tenancies t ON t.id=r.tenancy_id JOIN public.properties p ON p.id=t.property_id WHERE t.status IN ('active','expiring') AND r.amount-r.credit_applied>coalesce((SELECT sum(amount) FROM public.payments WHERE charge_id=r.id AND confirmation_status='confirmed'),0) AND r.due_on IN (today+3,today,today-3) LOOP INSERT INTO public.notifications(user_id,title,path,reference_id,event_key) VALUES(c.tenant_id,'Renta de '||c.name||' · vencimiento '||to_char(c.due_on,'DD/MM/YYYY'),'/payments',c.id,'rent-'||c.id||'-'||today) ON CONFLICT(event_key) DO NOTHING; IF c.due_on<today THEN INSERT INTO public.notifications(user_id,title,path,reference_id,event_key) VALUES(c.landlord_id,'Cargo vencido · '||c.name,'/payments',c.id,'overdue-'||c.id||'-'||today) ON CONFLICT(event_key) DO NOTHING; END IF; END LOOP; FOR t IN SELECT * FROM public.tenancies WHERE status IN ('active','expiring') AND end_date IN (today+60,today+30) LOOP INSERT INTO public.notifications(user_id,title,path,reference_id,event_key) VALUES(t.landlord_id,'Contrato próximo a terminar · '||to_char(t.end_date,'DD/MM/YYYY'),'/contracts',t.id,'end-'||t.id||'-'||today) ON CONFLICT(event_key) DO NOTHING; END LOOP; END; $$;
REVOKE ALL ON FUNCTION public.refresh_rental_reminders() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.refresh_rental_reminders() TO service_role;